import { useState, KeyboardEvent, ChangeEvent } from 'react';
import { JxInput, JxBadge, JxButton, JxField } from '@jinx-ui/react';

interface ArticleTagInputProps {
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  placeholder?: string;
  label?: string;
}

export default function ArticleTagInput({
  defaultValue = [],
  onChange,
  placeholder = 'Введите тег и нажмите Enter',
  label = 'Теги статьи',
}: ArticleTagInputProps) {
  const [tags, setTags] = useState<string[]>(defaultValue);
  const [draft, setDraft] = useState('');

  const commitTags = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const addTag = (raw: string) => {
    const cleaned = raw.trim();
    if (!cleaned || tags.includes(cleaned)) {
      setDraft('');
      return;
    }
    commitTags([...tags, cleaned]);
    setDraft('');
  };

  const removeTag = (tag: string) => {
    commitTags(tags.filter((t) => t !== tag));
  };

  const handleInputChange = (event: ChangeEvent<HTMLInputElement>) => {
    const value = event.target.value;
    if (value.endsWith(',')) {
      addTag(value.slice(0, -1));
      return;
    }
    setDraft(value);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      addTag(draft);
    } else if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      commitTags(tags.slice(0, -1));
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
      <JxField label={label} htmlFor="article-tag-input">
        <JxInput
          id="article-tag-input"
          value={draft}
          onChange={handleInputChange}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
        />
      </JxField>

      {tags.length > 0 && (
        <div
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            gap: 'var(--jx-space-1)',
            marginTop: 'var(--jx-space-1)',
          }}
        >
          {tags.map((tag) => (
            <JxBadge key={tag} variant="secondary">
              <span>{tag}</span>
              <JxButton
                variant="ghost"
                size="sm"
                aria-label={`Удалить тег ${tag}`}
                onClick={() => removeTag(tag)}
                style={{ marginInlineStart: 'var(--jx-space-1)' }}
              >
                ×
              </JxButton>
            </JxBadge>
          ))}
        </div>
      )}
    </div>
  );
}

